// Package id generates application-side identifiers.
//
// All primary keys are ULIDs generated by the application (P5): they sort by
// creation time, so they double as pagination cursors on every backend.
package id

import (
	"crypto/rand"
	"sync"
	"time"

	"github.com/oklog/ulid/v2"
)

var (
	mu      sync.Mutex
	entropy = ulid.Monotonic(rand.Reader, 0)
)

// New returns a new ULID string.
func New() string {
	mu.Lock()
	defer mu.Unlock()
	return ulid.MustNew(ulid.Timestamp(time.Now()), entropy).String()
}

// NewWithPrefix returns a ULID with a short type prefix, e.g. "ses_01J...".
func NewWithPrefix(prefix string) string {
	return prefix + "_" + New()
}

// Well-known prefixes. They only aid humans reading logs; code never parses them.
const (
	Tenant       = "ten"
	Session      = "ses"
	Message      = "msg"
	Turn         = "trn"
	Pending      = "pnd"
	ToolCall     = "tc"
	Artifact     = "art"
	Role         = "rol"
	Skill        = "skl"
	Workflow     = "wfd"
	Run          = "run"
	StepRun      = "stp"
	Schedule     = "sch"
	ScheduleRun  = "scr"
	MCPServer    = "mcp"
	Retrieval    = "rsc"
	Memory       = "mem"
	Audit        = "aud"
	APIKey       = "key"
	LLMCall      = "llm"
	Compaction   = "cmp"
	RiskOverride = "rsk"
	FeishuChat   = "fsc"
	FeishuThread = "fst"
)
